<script setup lang="ts">
import {computed} from 'vue'
const props=defineProps<{node:string;weather?:string;active:boolean}>()
const bank=computed(()=>props.node.startsWith('C_'))
const quiet=computed(()=>['rain_listen','rain_lull','C_holdfire','C_stop_signal'].includes(props.node))
</script>
<template><div v-if="active" class="river-light" :class="{bank,quiet,clear:weather==='clear'}" aria-hidden="true"><i class="mist far"></i><i class="mist near"></i><i class="reflection"></i><i class="torch"></i><span v-if="bank" v-for="i in 9" :key="i" class="ember" :style="{'--i':i}"></span></div></template>
<style scoped>
.river-light{position:fixed;inset:0;pointer-events:none;z-index:-3;overflow:hidden}.mist{position:absolute;width:160%;left:-30%;height:22%;top:42%;opacity:.24;background:radial-gradient(ellipse at 38% 70%,#a9c7d02a,transparent 55%),radial-gradient(ellipse at 74% 50%,#c6dde125,transparent 60%);filter:blur(16px);animation:current 31s ease-in-out infinite alternate}.mist.near{top:57%;opacity:.15;animation-duration:43s;animation-direction:alternate-reverse}.clear .mist{display:none}.reflection{position:absolute;left:18%;right:10%;bottom:16%;height:34%;opacity:.25;mix-blend-mode:screen;background:repeating-linear-gradient(174deg,transparent 0 19px,#c7d5da15 20px 22px,transparent 23px 38px);mask-image:radial-gradient(ellipse at center,black,transparent 67%);animation:water 9s ease-in-out infinite alternate}.bank .reflection{left:48%;bottom:22%;width:45%}.torch{position:absolute;left:2%;top:12%;width:17%;height:38%;background:radial-gradient(ellipse,#e6a75212,transparent 70%);mix-blend-mode:screen;animation:lantern 3.7s ease-in-out infinite alternate}.quiet .torch{animation-duration:6.5s}.ember{position:absolute;left:calc(3% + var(--i)*1.4%);top:36%;width:2px;height:3px;border-radius:60%;background:#fac379;box-shadow:0 0 5px #e5a744;opacity:0;animation:ember calc(5s + var(--i)*.5s) calc(var(--i)*-.8s) infinite}.quiet .ember{display:none}@keyframes current{to{transform:translateX(14%) scaleY(1.25)}}@keyframes water{to{transform:translateY(6px) skewX(4deg);opacity:.10}}@keyframes lantern{0%,50%,100%{opacity:.45}18%,75%{opacity:1}}@keyframes ember{10%{opacity:.6}80%{transform:translate(20px,-150px);opacity:0}}@media(prefers-reduced-motion:reduce){.river-light{display:none}}
